"""Bounded, replayable evidence acquisition. Stage facts never come from the LLM."""
import json
import re
from challenge_generator import configuration, SUBJECTS, CONTEXTS, Random

VERSION = 'evidence-journey-v1'
CHOICES = {
    'origin': {'label':'Trace the evidence origin', 'cost':1, 'purpose':'Find whether the existing check is independent or copied. This does not establish its scope.'},
    'scope': {'label':'Check applicability', 'cost':1, 'purpose':'Find whether the existing comparison addresses the same claim. This does not establish independence.'},
    'explanation': {'label':'Audit the proposed explanation', 'cost':1, 'purpose':'Find whether a documented transformation accounts for the discrepancy. An explanation alone does not qualify the cross-check.'},
    'independent': {'label':'Commission an independent comparison', 'cost':2, 'purpose':'Obtain a separately sourced comparison for the same scope. This does not establish why the discrepancy occurred.'},
    'defer': {'label':'Preserve the remaining budget', 'cost':0, 'purpose':'Obtain no new evidence. A limited conclusion can still be justified; unused budget is not a score.'},
}

def validated(value):
    if not isinstance(value,dict) or set(value)-{'version','config','choices'}:
        raise ValueError('Use a version, scenario configuration and a choice path.')
    if value.get('version',VERSION)!=VERSION: raise ValueError('This staged-review version is unavailable.')
    config=configuration(value.get('config',{})); choices=value.get('choices',[])
    if not isinstance(choices,list) or len(choices)>2 or any(not isinstance(c,str) or c not in CHOICES for c in choices):
        raise ValueError('Choose at most two listed evidence actions.')
    if sum(CHOICES[c]['cost'] for c in choices)>3: raise ValueError('This path exceeds the three-credit budget.')
    if len([c for c in choices if c!='defer'])!=len(set(c for c in choices if c!='defer')):
        raise ValueError('A completed evidence action cannot be purchased again.')
    return {'version':VERSION,'config':config,'choices':choices}

def source_for(title,description,labels,facts,rules,targets,marker):
    clauses=[f'f{i}: "{p}"' for i,p in enumerate(facts)]+[f'r{i}: "'+ ' & '.join(before)+' ==> '+after+'"' for i,(before,after) in enumerate(rules)]
    return ('theory Thread_Stage imports Main begin\n'+marker+'\n'
        +f'(* thread:title {title} *)\n(* thread:description {description} *)\n(* thread:goal '+','.join(targets)+' *)\n'
        +'\n'.join(f'(* thread:label {p} = {label} *)' for p,label in labels.items())
        +'\nlocale Thread_Stage_Case = fixes '+' '.join(labels)+' :: "bool"\nassumes '+'\n  and '.join(clauses)+'\nbegin end end\n')

def tutorial():
    labels={'pass':'My archive pass is valid','booked':'My archive visit is booked','open':'The archive is open',
            'ready':'My archive visit is ready','enter':'I may enter the archive'}
    title='Tutorial · The archive visit'
    description='I am visiting a fictional archive. I will practise stating a thought, reviewing its interpretation, checking it, and explaining the connection. No prior logic vocabulary is needed.'
    source=source_for(title,description,labels,['pass','booked','open'],[(['pass','booked'],'ready'),(['ready','open'],'enter')],['ready','enter'],'(* thread:lesson archive-v1 *)')
    return {'source':source,'tutorial':{'version':'archive-v1','steps':['ready','enter']},'difficulty':'Tutorial · guided practice',
            'goal':'Establish that my visit is ready, then that I may enter. I can explain connected parts together.',
            'hints':['Which two given conditions make my visit ready?','Once my visit is ready, which extra condition lets me enter?'],
            'debrief':'Which rule connects the facts to my conclusion? How did reviewing the interpretation protect my meaning?'}

def generate(value):
    spec=validated(value); c=spec['config']; path=spec['choices']; stage=len(path)+1
    sub=SUBJECTS[c['subject']]; ctx=CONTEXTS[c['context']]
    rng=Random(VERSION+'|'+c['seed']+'|'+c['difficulty'])
    name=rng.choose(['Cedar','Lumen','Aster','Vale','Mosaic','Harbour'])
    # The evidence world is fixed before the path is chosen. Choice reveals
    # different portions of that world; it never rewards a preferred conclusion.
    independent=rng.choose([True,False]); fits=rng.choose([True,False]); explained=rng.choose([True,False])
    labels={
      'trace':f'The source and version of the {sub["original"]} for {name} are recorded',
      'comparison':f'The source and reported {sub["record"]} for {name} were compared item by item',
      'independent':f'The current cross-check of {name} has a separate evidence origin',
      'shared':f'The existing cross-check of {name} copies its evidence origin',
      'fits':f'The current cross-check of {name} addresses {sub["scope"]}',
      'scope_gap':f'The existing cross-check of {name} addresses a different scope',
      'explained':f'A recorded {sub["explanation"]} exactly accounts for the discrepancy in {name}',
      'unresolved':f'The completed explanation audit leaves the discrepancy in {name} unexplained',
      'coverage_gap':'At this stage, the collected checks do not establish all the conditions for a disposition',
      'usable':f'The discrepancy in {name} has a traceable comparison record',
      'qualified':f'The current cross-check of {name} is independent and applicable',
      'gap':f'The evidence collected at this stage cannot settle the review of {name}',
      'review':f'{ctx["review"]} {name}',
      'close':f'{ctx["close"]} {name}',
      'wait':f'{ctx["wait"]} {name}',
      'boundary':('The brief states that a discrepancy alone cannot establish intent or misconduct' if c['context']=='misconduct' else 'The brief states that a discrepancy alone cannot establish a cause or claims beyond the compared record'),
      'limits':'My conclusion is limited to this record and the checks collected at this stage',
      'report':'My stage report records a justified next action and the limits of the evidence',
    }
    facts=['trace','comparison','boundary']
    if 'origin' in path:facts.append('independent' if independent else 'shared')
    if 'scope' in path:facts.append('fits' if fits else 'scope_gap')
    if 'independent' in path:facts+=['independent','fits']
    if 'explanation' in path:facts.append('explained' if explained else 'unresolved')
    facts=list(dict.fromkeys(facts))
    if not {'independent','fits'}<=set(facts) or not {'explained','unresolved'}&set(facts):facts.append('coverage_gap')
    rules=[(['trace','comparison'],'usable'),(['usable','independent','fits'],'qualified'),
           (['usable','coverage_gap'],'gap'),(['gap'],'wait'),(['qualified','explained'],'close'),
           (['qualified','unresolved'],'review'),(['usable','boundary'],'limits')]
    for d in ['wait','close','review']:rules.append(([d,'limits'],'report'))
    if c['difficulty']!='guided':
        labels['repetition']=f'The report has been repeated in {rng.choose([6,12,24])} summaries that do not identify separate origins'
        labels['endorsement']='A fictional committee supports the report but supplies no additional observation'
        facts+=['repetition','endorsement']
    if c['difficulty']=='stretch':
        labels.update(changed='In a separate hypothetical case, the new comparison addresses a different population or version',changed_limit='The hypothetical comparison cannot settle the original claim',separate_case='The hypothetical result does not replace the observations collected in this stage')
        facts.append('changed');rules.extend([(['changed'],'changed_limit'),(['changed','boundary'],'separate_case')])
    # Single disposition is an invariant, including paths that collect too little.
    reachable=set(facts)
    for _ in labels:
        for before,after in rules:
            if set(before)<=reachable:reachable.add(after)
    if len(reachable&{'wait','close','review'})!=1:raise ValueError('Could not construct a consistent stage.')
    remaining=3-sum(CHOICES[p]['cost'] for p in path)
    available=[dict(id=k,**v,remaining=remaining-v['cost']) for k,v in CHOICES.items() if v['cost']<=remaining and (k=='defer' or k not in path)] if stage<3 else []
    title=f'The Evidence Review · Stage {stage} of 3'
    description=f'I review a disputed {sub["record"]}, {name}, in {ctx["setting"]}. I decide what the evidence currently supports, then choose which check to fund. Reports are allegations to examine. All observations and rules are fictional.'
    source=source_for(title,description,labels,facts,rules,['report','limits'], '(* thread:journey '+json.dumps(spec,sort_keys=True,separators=(',',':'))+' *)')
    requirements=[dict(id='basis',label='Record the traceable evidence basis',any_of=['usable'],cue='Which two observations make the comparison traceable?'),
                  dict(id='condition',label='Explain a qualifying condition or current evidence gap',any_of=['qualified','gap'],cue='Which conditions are established, and which checks have not yet been collected?'),
                  dict(id='decision',label='State the action justified at this stage',any_of=['review','close','wait'],cue='Does the supplied evidence support review, resolution, or waiting?'),
                  dict(id='limits',label='Keep the conclusion within its evidence',any_of=['limits'],cue='What does the current evidence leave undecided?'),
                  dict(id='report',label='Combine the action and limit',any_of=['report'],cue='Can I connect the action to the boundary of the conclusion?')]
    if c['difficulty']=='stretch':requirements.extend([dict(id='changed_limit',label='Limit the separate hypothetical inference',any_of=['changed_limit'],cue='What changes when the comparison concerns a different population or version?'),dict(id='separate_case',label='Keep the hypothetical separate',any_of=['separate_case'],cue='Does a hypothetical change replace an observation in my actual review?')])
    return dict(source=source,journey=dict(**spec,stage=stage,total=3,remaining=remaining,available=available,record=name,
        acquired=[dict(id=p,**CHOICES[p]) for p in path],stage_title=['Assess the starting evidence','Review the first new check','Make a bounded final recommendation'][stage-1]),
        challenge=dict(config=c,subject_label=sub['label'],context_label=ctx['label'],theme=ctx['theme'],content_preview=ctx['preview'],method=sub['method'],
         dossiers=[dict(name=name,report=f'{ctx["concern"]} {name}. This is a report to evaluate, not an established finding.',observations=facts,reason_options=['qualified','gap'],decision_options=['review','close','wait'])],
         requirements=requirements,hypothetical=None,concepts=['Evidence acquisition: choose a check that can distinguish possibilities, not just confirm my expectation.','Source independence and applicability are separate conditions.','Missing evidence is not proof of the opposite.','A justified decision is bounded by what has been collected.']),
        difficulty={'guided':'Supported','challenge':'Challenge','stretch':'Stretch'}[c['difficulty']]+' · three stages',
        goal='Establish the evidence basis, a qualifying condition or gap, a justified action, its limit, and a combined stage report.',
        hints=['Which conditions does the next inference actually need?','What could a new check reveal that would change my view?'],
        debrief='What did my chosen check add? Which alternative remains open? Was my choice useful even if it did not confirm my expectation?')

def metadata_from_source(text):
    markers=re.findall(r'\(\*\s*thread:(journey|lesson)\s+(.+?)\s*\*\)',text)
    if not markers:return {}
    if len(markers)!=1 or 'thread:challenge' in text:raise ValueError('Use one generated stage or tutorial marker.')
    kind,value=markers[0]
    if kind=='lesson':
        if value!='archive-v1':raise ValueError('Unknown tutorial version.')
        generated=tutorial()
    else:generated=generate(json.loads(value))
    if generated['source'].strip()!=text.strip():raise ValueError('This generated stage was edited. Regenerate it, or remove its generator marker to import an ordinary custom case.')
    return {k:v for k,v in generated.items() if k!='source'}

pacing.py:
"""Private, bounded proof anticipation. Predictions never become player evidence."""
from __future__ import annotations
import copy
import hashlib
import json
import threading
from collections import OrderedDict
import logic
from logic import core, theory

def formal_key(claim, accepted, scenario):
    if claim.get('domain') == 'theory':
        core_data={k:claim[k] for k in ('assumptions','conclusions')}
        context=[]
    else:
        parsed=core._claim(claim)
        core_data=core._theorem(parsed).json()
        context=[core._theorem(c).json() for c in core._dependencies(parsed,accepted)]
    envelope={'version':2,'scenario':scenario.get('source_hash',scenario['source_text']),
              'claim':core_data,'dependencies':context}
    return hashlib.sha256(json.dumps(envelope,sort_keys=True).encode()).hexdigest()

class ProofCache:
    def __init__(self, config):
        self.config=config
        self.lock=threading.RLock()
        self.entries=OrderedDict()
        self.pending={}
        self.worker=None

    def raw_verify(self, claim, accepted, scenario):
        return theory.verify_claim(claim,accepted,self.config,scenario) if scenario.get('domain')=='theory' else logic.verify_claim(claim,accepted,self.config)

    def remember(self,key,result):
        if result['status']!='verified': return
        with self.lock:
            self.entries[key]=copy.deepcopy(result)
            self.entries.move_to_end(key)
            while len(self.entries)>96: self.entries.popitem(last=False)

    def verify(self,claim,accepted,scenario):
        key=formal_key(claim,accepted,scenario)
        with self.lock: pending=self.pending.get(key)
        # If this exact proof is already running while the player reviews the
        # interpretation, use its remaining work rather than launch a duplicate.
        if pending: pending.wait(float(self.config.get('isabelle_timeout',180))+float(self.config.get('timeout',30))+20)
        with self.lock:
            cached=copy.deepcopy(self.entries.get(key))
        if cached:
            # Cached proof code contains only validated formal terms. Replace
            # every candidate/graph metadata field with actual player evidence.
            cached['claim']=copy.deepcopy(claim)
            if claim.get('domain')=='theory':
                cached['graph'].update(candidate=copy.deepcopy(claim),accepted=copy.deepcopy(accepted))
            else:
                parsed=core._claim(claim)
                cached['rendered']=logic.render_claim(claim)
                cached['graph']={'kind':'Boolean argument graph','candidate':copy.deepcopy(claim),'dependencies':[c.json() for c in core._dependencies(parsed,accepted)],'effective_theorem':core._theorem(parsed).json(),'search':'Iterative deepening DFS'}
            cached['timing']={'proof_reused':True}
            return cached
        result=self.raw_verify(claim,accepted,scenario)
        self.remember(key,result)
        result['timing']={'proof_reused':False}
        return result

    def anticipate(self,session,proposed=None):
        if not self.config.get('anticipation_enabled',True) or session['solved']: return
        with self.lock:
            if self.worker and self.worker.is_alive(): return
            # The private graph is never returned by session/export endpoints.
            accepted=copy.deepcopy(session['claims']); scenario=copy.deepcopy(session['scenario'])
            epoch=len(accepted)
            def work():
                try:
                    candidates=([copy.deepcopy(proposed)] if proposed else [])+predictions(accepted,scenario)
                    for claim in candidates[:2]:
                        if session['busy'] or len(session['claims'])!=epoch or session['solved']: return
                        key=formal_key(claim,accepted,scenario)
                        with self.lock: exists=key in self.entries
                        if exists: continue
                        event=threading.Event()
                        with self.lock: self.pending[key]=event
                        try:
                            result=self.raw_verify(claim,accepted,scenario)
                            self.remember(key,result)
                        finally:
                            with self.lock: self.pending.pop(key,None)
                            event.set()
                        if result['status']!='verified': continue
                        with self.lock:
                            session['anticipated_graph'][key]={'origin':'anticipated','visited':False,'validation':'Prolog + Isabelle/HOL','claim':claim}
                            while len(session['anticipated_graph'])>8: session['anticipated_graph'].pop(next(iter(session['anticipated_graph'])))
                except Exception:
                    # Speculation is optional; foreground verification remains
                    # authoritative and reports its own errors normally.
                    return
            self.worker=threading.Timer(0.8,work)
            self.worker.name='anticipation-proofs'; self.worker.daemon=True; self.worker.start()

def predictions(accepted,scenario):
    if scenario.get('domain')=='theory':
        visited={p['id'] for c in accepted for p in c['conclusions'] if p['positive']}
        facts={p for p,n in scenario['nodes'].items() if n['fact']}
        frontier=[r['conclusion'] for r in scenario['rules'] if r['conclusion'] not in visited and set(r['premises']) <= visited|facts]
        candidates=list(dict.fromkeys(frontier+scenario['targets']))
        return [dict(id='anticipated',domain='theory',kind='step',text='',assumptions=[],conclusions=[dict(id=p,positive=True)],depends_on=[]) for p in candidates if p not in visited]
    safe={'op':'atom','name':'safe'}
    truthful={'op':'atom','name':'truthful'}
    q={'op':'answer','guard':'asked','proposition':{'op':'answer','guard':'other','proposition':safe}}
    candidates=[]
    if accepted:
        last=accepted[-1]
        if len(last['assumptions'])==1 and last['assumptions'][0] in (truthful,{'op':'not','arg':truthful}):
            flipped=copy.deepcopy(last); flipped.update(id='anticipated',text='',depends_on=[])
            flipped['assumptions']=[{'op':'not','arg':truthful} if last['assumptions'][0]==truthful else truthful]
            candidates.append(flipped)
    candidates += [dict(id='anticipated',kind='step',text='',assumptions=[],conclusion={'op':'iff','left':q,'right':{'op':'not','arg':safe}},depends_on=[],strategy=None),
                   dict(id='anticipated',kind='solution',text='',assumptions=[],conclusion={'op':'const','value':True},depends_on=[],strategy={'question':q,'on_no':'tested','on_yes':'other'})]
    seen={formal_key(c,accepted,scenario) for c in accepted}
    return [logic.parse_claim(c) for c in candidates if formal_key(c,accepted,scenario) not in seen]

def argumentation_review(session, claim_view):
    claims=session['claims']; scenario=session['scenario']
    overview=[{'step':c['id'],'thought':c['text'],'conclusion':claim_view(c,scenario)['conclusion'],'depends_on':c['depends_on']} for c in claims]
    seen={}; repeated=[]
    for c in claims:
        key=formal_key(c,claims,scenario)
        if key in seen: repeated.append((c['id'],seen[key]))
        else: seen[key]=c['id']
    inefficiencies=[f"I repeated the same formal claim in {a} and {b}. I could refer back to the earlier step." for a,b in repeated]
    rejected=sum(h['result']['status'] in ('refuted','invalid_assumptions','unsupported') for h in session['history'])
    if rejected: inefficiencies.append(f"I revisited {rejected} attempt(s) after a check did not establish the claim. This exploration can eliminate approaches or reveal an interpretation that needs correcting. In the direct argument, I can make the relevant assumptions explicit.")
    if len(claims)>1 and not any(c['depends_on'] for c in claims):
        inefficiencies.append("I did not explicitly link my steps. Stating ‘from my earlier step…’ would make the argument easier to follow; it does not make the current conclusions invalid.")
    if scenario.get('domain')!='theory' and session.get('solution',{}):
        from logic.solution import _questions
        witness=session['solution'].get('witness') or {}
        if witness.get('question'):
            q=core._expr({'op':'answer','guard':'asked','proposition':witness['question']})
            exploratory=[c['id'] for c in claims if q not in list(_questions(core._theorem(core._claim(c))))]
            if exploratory:
                inefficiencies.append("Steps "+', '.join(exploratory)+" explore questions other than my final question. I could summarise that exploration when presenting the final argument, while retaining it in my learning trail.")
    if not inefficiencies: inefficiencies=["No repeated formal claim or rejected attempt was identified. This review does not claim that my argument is the shortest possible."]
    concepts={
      'two-guards':['Case analysis: I need my explanation to cover either guard.','Invariant reasoning: I look for an answer relationship that stays the same across cases.','Knowledge and action: identifying the doors and choosing a safe door are distinct obligations.'],
      'murder-basic':['Conjunction: all required criteria must hold together.','Sufficiency: one clue alone need not establish the conclusion.','Model boundaries: my conclusion depends on the fictional rule I was given.'],
      'murder-temporal':['Temporal coverage: a finding at one time does not cover an entire interval.','Evidence and inference: an association is different from accepted causation.','Separate obligations: I check each suspect against every required condition.'],
      'murder-fuzzy':['Ranking and proof: a larger score does not establish guilt.','Necessary conditions: a missing offence element blocks the model’s conviction rule.','Uncertainty: a suspicion degree is not a probability.'],
      'sqrt-two':['Proof by contradiction: incompatible requirements rule out a candidate.','Assumption tracking: I distinguish supplied expert facts from my deductions.'],
      'legal':['Conditional reasoning: I establish when a requirement applies.','Rule application: I compare each required condition with the facts.']}
    return dict(overview=overview,inefficiencies=inefficiencies,concepts=scenario.get('challenge',{}).get('concepts') or concepts.get(scenario['id'],['Premise-to-conclusion reasoning: I make each rule application explicit.','Assumption tracking: I separate given facts from derived conclusions.']),transfer=scenario.get('debrief','Where else could I use this style of argument?'))

nlp_vocabulary.py:
"""Conservative vocabulary narrowing for explicitly framed, verbatim claims.

This helper identifies labels that are already written out in full. It does
not interpret free prose, prove a claim, repair a model response, or replace
Gemma's interpretation and fidelity check. ``None`` means use the ordinary
unrestricted scenario vocabulary.
"""

from __future__ import annotations

from functools import lru_cache
import re
from typing import Any


_GIVEN = re.compile(r"given\s+that\s+")
_CONCLUDE = re.compile(r"i\s+conclude\s+that\s+")
_GIVEN_BOUNDARY = re.compile(r",\s*i\s+conclude\s+that\s+")
_BECAUSE = re.compile(r"(?:,\s*|\s+)because\s+")
_SEPARATORS = (
    re.compile(r"\s*;\s*and\s+that\s+"),
    re.compile(r"\s*;\s*"),
    re.compile(r"\s+and\s+that\s+"),
)

# Deliberately small: unsupported inflections fall back to the full dictionary.
_NEGATIVE_VERBS = {
    "satisfies": "satisfy",
    "meets": "meet",
    "supports": "support",
    "requires": "require",
    "establishes": "establish",
    "permits": "permit",
    "contains": "contain",
    "covers": "cover",
}
_PREDICATE = re.compile(r"\b(?:is|are|" + "|".join(_NEGATIVE_VERBS) + r")\b", re.I)
_COMPLEX_NEGATIVE_SCOPE = re.compile(
    r"\b(?:and|or|nor|but|if|then|unless|when|whenever|where|wherever|while|"
    r"because|since|given|provided|assuming|whether|that|who|whose|which|"
    r"not|no|never|neither|without|cannot|none|nothing|nobody|"
    r"all|every|each|some|any|both|either|only|exactly|always|sometimes|"
    r"must|may|might|could|would|should|can|will|necessarily|possibly|"
    r"maybe|perhaps|probably|possibly|apparently|allegedly|reportedly|"
    r"believes|thinks|claims|says|knows|seems|appears|predicts|suggests|"
    r"states|argues|assumes|hopes|expects|suspects|"
    r"under|across|during|before|after|throughout|within|beyond|"
    r"absent|unsafe|incomplete|unverified|insufficient|unavailable|"
    r"fails|lacks|excluded|denied)\b"
)


def _fold(value: str) -> str:
    value = value.strip().casefold()
    # Permit an ordinary final full stop, without stripping question marks,
    # uncertainty, negation, sentence content or arbitrary punctuation.
    return value[:-1].rstrip() if value.endswith(".") else value


def exact_reason_vocabulary(text: str, vocabulary: list[dict[str, Any]]) -> dict[str, list[str]] | None:
    """Find exact assumption/conclusion labels in explicit sentence forms.

    Supported forms are ``Given that A, I conclude that C`` and ``C because A``;
    the latter may start with ``I conclude that``. A separate compound assertion
    form is ``I conclude that A; and that B``, containing at least two distinct
    labels and no stated reasons. Each role can contain labels
    joined by a semicolon, ``; and that``, or ``and that``. Bare ``and`` stays
    inside a label. Matching ignores case and a final full stop only, apart from
    whitespace around the explicit framing and separators.

    Every character of each role must be consumed by unambiguous full labels.
    Multiple possible complete parses, including a long label versus two shorter
    labels, return ``None``. Nothing is selected by substring or approximate match.
    """
    if not isinstance(text, str) or not text.strip() or len(text) > 8000:
        return None
    if not isinstance(vocabulary, list) or not vocabulary or len(vocabulary) > 512:
        return None

    by_label: dict[str, set[str]] = {}
    by_id: dict[str, str] = {}
    for item in vocabulary:
        if not isinstance(item, dict):
            return None
        claim_id, meaning = item.get("id"), item.get("meaning")
        if not isinstance(claim_id, str) or not claim_id or not isinstance(meaning, str):
            return None
        meaning = _fold(meaning)
        if not meaning or len(meaning) > 8000:
            return None
        if claim_id in by_id and by_id[claim_id] != meaning:
            return None
        by_id[claim_id] = meaning
        by_label.setdefault(meaning, set()).add(claim_id)
    labels = tuple((label, tuple(sorted(ids))) for label, ids in by_label.items())

    def parse_labels(fragment: str) -> set[tuple[str, ...]]:
        fragment = fragment.strip()
        if not fragment:
            return set()

        @lru_cache(maxsize=None)
        def visit(position: int, remaining: int) -> frozenset[tuple[str, ...]]:
            if remaining == 0:
                return frozenset()
            answers: set[tuple[str, ...]] = set()
            for label, ids in labels:
                if not fragment.startswith(label, position):
                    continue
                end = position + len(label)
                if end == len(fragment):
                    tails = {()}
                else:
                    tails: set[tuple[str, ...]] = set()
                    for separator in _SEPARATORS:
                        match = separator.match(fragment, end)
                        if match and match.end() < len(fragment):
                            tails.update(visit(match.end(), remaining - 1))
                            if len(tails) > 1:
                                break
                for claim_id in ids:
                    for tail in tails:
                        answers.add((claim_id, *tail))
                        # Only uniqueness matters. Keeping two complete parses
                        # avoids exponential exploration of ambiguous dictionaries.
                        if len(answers) > 1:
                            return frozenset(answers)
            return frozenset(answers)

        return set(visit(0, 12))

    sentence = _fold(text)
    frames: list[tuple[str, str]] = []
    given = _GIVEN.match(sentence)
    if given:
        for boundary in _GIVEN_BOUNDARY.finditer(sentence, given.end()):
            frames.append((sentence[given.end():boundary.start()], sentence[boundary.end():]))

    conclusion_prefix = _CONCLUDE.match(sentence)
    because_start = conclusion_prefix.end() if conclusion_prefix else 0
    for boundary in _BECAUSE.finditer(sentence):
        if boundary.start() >= because_start:
            frames.append((sentence[boundary.end():], sentence[because_start:boundary.start()]))

    results: set[tuple[tuple[str, ...], tuple[str, ...]]] = set()
    if conclusion_prefix:
        # Parse the entire framed assertion before considering it a compound.
        # A long dictionary label competing with several shorter labels remains
        # ambiguous, even though the single-label parse is not this fast path.
        compound = parse_labels(sentence[conclusion_prefix.end():])
        if len(compound) > 1:
            return None
        if compound:
            asserted = next(iter(compound))
            if len(asserted) >= 2:
                if len(set(asserted)) != len(asserted):
                    return None
                results.add(((), asserted))
    for assumptions_text, conclusions_text in frames:
        assumptions = parse_labels(assumptions_text)
        conclusions = parse_labels(conclusions_text)
        for premises in assumptions:
            for asserted in conclusions:
                results.add((premises, asserted))
                if len(results) > 1:
                    return None
    if len(results) != 1:
        return None
    assumptions, conclusions = next(iter(results))
    return {"assumptions": list(dict.fromkeys(assumptions)),
            "conclusions": list(dict.fromkeys(conclusions))}


def _simple_negative_subject(subject: str) -> bool:
    """Restrict generated inflections to short, uncomplicated noun phrases."""
    words = subject.split()
    if not words or len(words) > 5:
        return False
    if any(not re.fullmatch(r"[^\W\d][\w'’-]*", word) for word in words):
        return False
    if len(words) == 1:
        return True
    if words[0].casefold() in {"the", "a", "an"}:
        return True
    # Multiple proper-name words are allowed; an embedded verb between names is
    # not treated as part of a simple subject merely because a later verb matches.
    return all(word[0].isupper() for word in words)


def exact_negative_vocabulary(text: str, vocabulary: list[dict[str, Any]]) -> list[str] | None:
    """Identify the label explicitly negated by a complete canonical sentence.

    ``It is not the case that LABEL`` gives explicit whole-label scope and may
    negate a complex label. Otherwise this helper supports only ``is not``,
    ``are not`` and ``does not`` plus an entry from ``_NEGATIVE_VERBS``. Those
    alternatives are generated only for simple clauses without connectives,
    conditions, negation, quantifiers, uncertainty or other scope markers.

    The result narrows vocabulary only. Gemma must still return the polarity,
    and its interpretation still needs fidelity checking and user confirmation.
    An exact positive dictionary label or multiple complete matches makes the
    sentence ambiguous for this purpose, so the function returns ``None``.
    """
    if not isinstance(text, str) or not text.strip() or len(text) > 8000:
        return None
    if not isinstance(vocabulary, list) or not vocabulary or len(vocabulary) > 512:
        return None
    sentence = _fold(text)
    labels: list[tuple[str, str, str]] = []
    seen_ids: dict[str, str] = {}
    for item in vocabulary:
        if not isinstance(item, dict):
            return None
        claim_id, meaning = item.get("id"), item.get("meaning")
        if not isinstance(claim_id, str) or not claim_id or not isinstance(meaning, str):
            return None
        folded = _fold(meaning)
        if not folded or len(meaning) > 8000:
            return None
        if claim_id in seen_ids and seen_ids[claim_id] != folded:
            return None
        if sentence == folded:
            return None
        seen_ids[claim_id] = folded
        original = meaning.strip()
        if original.endswith("."):
            original = original[:-1].rstrip()
        labels.append((claim_id, original, folded))

    matches: set[str] = set()
    for claim_id, original, folded in labels:
        if sentence == "it is not the case that " + folded:
            matches.add(claim_id)
            continue
        if (_COMPLEX_NEGATIVE_SCOPE.search(folded)
                or re.search(r"[.,;:!?()\[\]{}\"]", folded)
                or re.search(r"\b\w+n['’]t\b", folded)):
            continue
        predicates = list(_PREDICATE.finditer(original))
        if len(predicates) != 1:
            continue
        predicate = predicates[0]
        subject = original[:predicate.start()].strip()
        complement = original[predicate.end():].strip()
        if not complement or not _simple_negative_subject(subject):
            continue
        verb = predicate.group().casefold()
        negative = (verb + " not") if verb in ("is", "are") else ("does not " + _NEGATIVE_VERBS[verb])
        candidate = f"{subject} {negative} {complement}".casefold()
        if sentence == candidate:
            matches.add(claim_id)
    return [next(iter(matches))] if len(matches) == 1 else None
